  "packageRules": [
    {
      "description": "Alpine apk pins in app Dockerfiles (e.g. hd-idle=1.22-r8): read the apk datasource's versions from the Alpine binary repositories and bump the app's config.yaml version in the same PR (experimental bumpVersions feature; generic for all apps). Renovate cannot infer the branch from the base-image ARG default – without registryUrls it silently skips these pins (skipReason unknown-registry) – so the branch is pinned here; update it together with the Dockerfile BUILD_FROM default on a base-image bump (the validate:apk-pins drift check derives the branch dynamically and cross-checks the pins either way). The changelog entry for the bumped version is filled post-merge by the apk-bump workflow (CI; the hosted Renovate app cannot run post-upgrade tasks). Merge behavior and grouping are decided per update type by the chained apk rules below – see the repository-root KNOWLEDGE.md apk package version policy.",
      "matchDatasources": [
        "apk"
      ],
      "bumpVersions": [
        {
          "name": "app config version bump for apk pin updates",
          "filePatterns": [
